/** Accept both the gateway's stable code and older/newer runtime category shapes. */
export function isInsufficientBalanceFailure(value: unknown): boolean {
    const mapped = modelFailure('en', value);
    if (mapped.kind !== 'unknown') return mapped.kind === 'balance_insufficient';
    const records: Readonly<Record<string, unknown>>[] = [];
    if (value instanceof Error) records.push({ message: value.message, name: value.name });
    else if (value && typeof value === 'object' && !Array.isArray(value)) {
        const root = value as Readonly<Record<string, unknown>>;
        records.push(root);
        for (const key of ['error', 'failure', 'details', 'cause']) {
            const nested = root[key];
            if (nested && typeof nested === 'object' && !Array.isArray(nested)) records.push(nested as Readonly<Record<string, unknown>>);
        }
    }
    const code = records.map(record => typeof record.code === 'string' ? record.code.trim().toLocaleLowerCase() : '').find(Boolean) || '';
    const kind = records.some(record => typeof record.kind === 'string' && record.kind.trim().toLocaleLowerCase() === 'insufficient_balance');
    const status = records.map(record => Number(record.status ?? record.httpStatus)).find(candidate => Number.isSafeInteger(candidate) && candidate === 402);
    const message = records.map(record => typeof record.message === 'string' ? record.message : '').find(Boolean) || (typeof value === 'string' ? value : '');
    return code === 'wallet_balance_insufficient' || code === 'insufficient_balance' || kind || status === 402
        || /(?:insufficient\s+balance|余额不足|余额不够|잔액이 부족|saldo insuficiente)/i.test(message);
}

function finiteNonNegativeNumber(value: unknown, fallback = 0): number {
    return typeof value === 'number' && Number.isFinite(value) ? Math.max(0, value) : fallback;
}

function finiteNonNegativeInteger(value: unknown, fallback = 0): number {
    return Math.floor(finiteNonNegativeNumber(value, fallback));
}

function normalizeAgentChildReceipt(value: unknown): AgentChildReceipt | undefined {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
    const candidate = value as Record<string, unknown>;
    if (!['completed', 'partial', 'cancelled', 'failed', 'unknown'].includes(String(candidate.outcome))) return undefined;
    const failure = candidate.failure && typeof candidate.failure === 'object' && !Array.isArray(candidate.failure)
        ? candidate.failure as Record<string, unknown> : undefined;
    return {
        outcome: candidate.outcome as AgentChildReceipt['outcome'],
        retrySafe: candidate.retrySafe === true,
        unknownSideEffect: candidate.unknownSideEffect === true,
        summary: typeof candidate.summary === 'string' ? candidate.summary.slice(0, 300) : '',
        ...(failure && typeof failure.code === 'string' && typeof failure.message === 'string' ? {
            failure: {
                code: failure.code.slice(0, 160),
                message: failure.message.replace(/[\u0000\r\n]+/g, ' ').slice(0, 2_000)
            }
        } : {})
    };
}

function isBrowserNavigationToolName(name: string): boolean {
    const parts = name.trim().toLowerCase().split(/[._-]+/g).filter(Boolean);
    if (!parts.length) return false;
    const verb = parts.at(-1);
    const subject = parts.at(-2);
    const navigationVerbs = ['open', 'navigate', 'visit', 'view', 'preview', 'load', 'go'];
    const targetWords = ['url', 'page', 'site', 'browser', 'web'];
    if (parts.includes('browser') && navigationVerbs.includes(verb || '')) return true;
    if (parts.includes('playwright') && navigationVerbs.includes(verb || '')) return true;
    if (parts.includes('preview') && navigationVerbs.includes(verb || '')) return true;
    if (['web', 'site'].includes(subject || '') && navigationVerbs.includes(verb || '')) return true;
    return navigationVerbs.slice(0, 3).includes(verb || '') && targetWords.includes(subject || '');
}

function agentChildDomId(prefix: string, childRunId: string): string {
    return `${prefix}-${childRunId.replace(/[^A-Za-z0-9_-]/g, '-')}`;
}

interface AgentChildScrollState {
    readonly top: number;
    readonly wasAtBottom: boolean;
    readonly unseenUpdates: number;
    readonly contentRevision: string;
}

type AgentChildScrollStateMap = Readonly<Record<string, AgentChildScrollState>>;

function normalizeAgentChildScrollStates(value: unknown): AgentChildScrollStateMap {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    const result: Record<string, AgentChildScrollState> = {};
    for (const [childRunId, candidate] of Object.entries(value as Record<string, unknown>).slice(0, MAX_PERSISTED_AGENT_CHILD_SCROLL_STATES)) {
        if (!/^[A-Za-z0-9._:-]{1,200}$/.test(childRunId)
            || childRunId === '__proto__' || childRunId === 'constructor' || childRunId === 'prototype'
            || !candidate || typeof candidate !== 'object' || Array.isArray(candidate)) continue;
        const state = candidate as Record<string, unknown>;
        const top = finiteNonNegativeNumber(state.top);
        const unseenUpdates = Math.min(99, finiteNonNegativeInteger(state.unseenUpdates));
        const contentRevision = typeof state.contentRevision === 'string'
            ? state.contentRevision.slice(0, 300) : '';
        Object.defineProperty(result, childRunId, {
            value: {
                top,
                wasAtBottom: state.wasAtBottom !== false,
                unseenUpdates,
                contentRevision
            },
            enumerable: true,
            configurable: true,
            writable: true
        });
    }
    return result;
}

/** Children saved as running in a finished turn were cut off with that turn's run. */
function settleSavedAgentChildren(children: readonly DesktopAgentChildSnapshot[]): readonly DesktopAgentChildSnapshot[] {
    return children.some(child => child.status === 'running')
        ? children.map(child => child.status === 'running' ? { ...child, status: 'interrupted' as const } : child)
        : children;
}

function normalizeAgentChildSnapshots(value: unknown): readonly DesktopAgentChildSnapshot[] {
    if (!Array.isArray(value)) return [];
    const candidates = value.filter((candidate): candidate is Record<string, unknown> => Boolean(
        candidate && typeof candidate === 'object' && !Array.isArray(candidate)
        && typeof candidate.childRunId === 'string' && typeof candidate.parentRunId === 'string'
        && typeof candidate.rootRunId === 'string' && typeof candidate.task === 'string'
        && DESKTOP_AGENT_CHILD_STATUSES.has(String(candidate.status))
        && candidate.taskContext && typeof candidate.taskContext === 'object' && !Array.isArray(candidate.taskContext)
    )).filter((candidate, _index, all) => {
        const childRunId = typeof candidate.childRunId === 'string' ? candidate.childRunId.trim().slice(0, 200) : '';
        return Boolean(childRunId) && all.findIndex(other =>
            typeof other.childRunId === 'string' && other.childRunId.trim().slice(0, 200) === childRunId
        ) === _index;
    }).slice(0, MAX_PERSISTED_AGENT_CHILDREN);
    return candidates.map(candidate => {
        const rawContext = candidate.taskContext as Record<string, unknown>;
        const childRunId = typeof candidate.childRunId === 'string' ? candidate.childRunId.trim().slice(0, 200) : '';
        const parentRunId = typeof candidate.parentRunId === 'string' ? candidate.parentRunId.trim().slice(0, 200) : '';
        const rootRunId = typeof candidate.rootRunId === 'string' ? candidate.rootRunId.trim().slice(0, 200) : '';
        const depth = Math.min(4, finiteNonNegativeInteger(candidate.depth));
        const firstEventIndex = finiteNonNegativeInteger(candidate.firstEventIndex);
        const selectedMemory = Array.isArray(rawContext.selectedMemory)
            ? rawContext.selectedMemory.filter((item): item is Record<string, unknown> => Boolean(
                item && typeof item === 'object' && !Array.isArray(item)
                && typeof (item as Record<string, unknown>).id === 'string'
                && /^[A-Za-z0-9][A-Za-z0-9._:/-]{0,239}$/.test(String((item as Record<string, unknown>).id).trim())
                && ['summary', 'file_ref', 'checkpoint_ref', 'message_ref'].includes(String((item as Record<string, unknown>).kind))
            )).slice(0, 16).map(item => {
                const maxCharacters = typeof item.maxCharacters === 'number' && Number.isSafeInteger(item.maxCharacters)
                    ? Math.max(1, Math.min(4_000, item.maxCharacters)) : 2_000;
                const text = typeof item.text === 'string'
                    ? item.text.replace(/[\u0000\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, maxCharacters)
                        .replace(/\bsk-[A-Za-z0-9_-]{12,}\b/g, '[redacted]')
                        .replace(/\bBearer\s+[A-Za-z0-9._~+/=-]{8,}\b/gi, 'Bearer [redacted]') : '';
                const ref = typeof item.ref === 'string'
                    ? item.ref.replace(/[\u0000\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 2_000) : '';
                if (!text && !ref) return undefined;
                return {
                    id: String(item.id).trim().slice(0, 240),
                    kind: item.kind as AgentContextMemoryItem['kind'],
                    ...(text ? { text } : {}),
                    ...(ref ? { ref } : {}),
                    ...(typeof item.sourceRunId === 'string'
                        && /^[A-Za-z0-9][A-Za-z0-9._:/-]{0,239}$/.test(item.sourceRunId.trim())
                        ? { sourceRunId: item.sourceRunId.trim().slice(0, 240) } : {}),
                    maxCharacters
                };
            }).filter((item): item is AgentContextMemoryItem => Boolean(item)) : [];
        const context = {
            version: 1 as const,
            workspaceRoot: typeof rawContext.workspaceRoot === 'string' ? rawContext.workspaceRoot.slice(0, 4_096) : '',
            ...(typeof rawContext.conversationId === 'string' ? { conversationId: rawContext.conversationId.slice(0, 300) } : {}),
            goal: typeof rawContext.goal === 'string' ? rawContext.goal.slice(0, 20_000) : (typeof candidate.task === 'string' ? candidate.task.slice(0, 20_000) : ''),
            ...(typeof rawContext.parentGoal === 'string' ? { parentGoal: rawContext.parentGoal.slice(0, 20_000) } : {}),
            constraints: Array.isArray(rawContext.constraints) ? rawContext.constraints.filter((item): item is string => typeof item === 'string').slice(0, 16).map(item => item.slice(0, 600)) : [],
            relevantPaths: Array.isArray(rawContext.relevantPaths) ? rawContext.relevantPaths.filter((item): item is string => typeof item === 'string').slice(0, 64).map(item => item.slice(0, 1_000)) : [],
            recentOperations: Array.isArray(rawContext.recentOperations) ? rawContext.recentOperations.filter((item): item is string => typeof item === 'string').slice(-12).map(item => item.slice(0, 700)) : [],
            ...(rawContext.recentOperationsCanonical === true ? { recentOperationsCanonical: true as const } : {}),
            parentRunId,
            rootRunId,
            depth,
            permissionMode: (rawContext.permissionMode === 'read_only' || rawContext.permissionMode === 'full_access'
                ? rawContext.permissionMode : 'full_access') as AgentPermissionMode,
            allowedToolNames: Array.isArray(rawContext.allowedToolNames) ? rawContext.allowedToolNames.filter((item): item is string => typeof item === 'string' && /^[a-z][a-z0-9]*(?:[._-][a-z0-9]+)+$/.test(item)).slice(0, 128).map(item => item.slice(0, 500)) : [],
            ...(typeof rawContext.modelId === 'string' ? { modelId: rawContext.modelId.slice(0, 240) } : {}),
            ...(typeof rawContext.locale === 'string' ? { locale: rawContext.locale.slice(0, 32) } : {}),
            selectedMemory
        };
        const events = Array.isArray(candidate.events)
            ? candidate.events.filter((event): event is AgentRunEvent => Boolean(
                event && typeof event === 'object' && !Array.isArray(event)
                && DESKTOP_AGENT_EVENT_TYPES.has(String((event as Record<string, unknown>).type))
                && typeof (event as Record<string, unknown>).at === 'string'
            )).slice(-MAX_PERSISTED_AGENT_CHILD_EVENTS)
            : [];
        const nextEventIndex = Math.max(firstEventIndex + events.length,
            finiteNonNegativeInteger(candidate.nextEventIndex, firstEventIndex + events.length));
        const eventCount = Math.min(MAX_PERSISTED_AGENT_CHILD_EVENTS, Math.max(
            events.length,
            finiteNonNegativeInteger(candidate.eventCount),
            nextEventIndex
        ));
        const result = candidate.result && typeof candidate.result === 'object' && !Array.isArray(candidate.result)
            ? candidate.result as Record<string, unknown> : undefined;
        const receipt = normalizeAgentChildReceipt(candidate.receipt);
        const error = candidate.error && typeof candidate.error === 'object' && !Array.isArray(candidate.error)
            ? candidate.error as Record<string, unknown> : undefined;
        const status = candidate.status as DesktopAgentChildSnapshot['status'];
        const startedAt = finiteNonNegativeNumber(candidate.startedAt);
        const updatedAt = Math.max(startedAt, finiteNonNegativeNumber(candidate.updatedAt));
        const normalizedError: DesktopAgentRunFailure | undefined = error && typeof error.code === 'string' && typeof error.message === 'string' ? {
            code: error.code.slice(0, 200),
            message: error.message.slice(0, 2_000),
            ...(error.readableError ? { readableError: modelFailure('en', error.readableError) } : {}),
            kind: (typeof error.kind === 'string' && DESKTOP_AGENT_FAILURE_KINDS.has(error.kind) ? error.kind : 'failed') as DesktopAgentRunFailure['kind'],
            retryable: error.retryable === true,
            ...(typeof error.retrySafe === 'boolean' ? { retrySafe: error.retrySafe } : {}),
            resumable: error.resumable === true,
            ...(typeof error.httpStatus === 'number' && Number.isFinite(error.httpStatus)
                ? { httpStatus: Math.max(0, Math.floor(error.httpStatus)) } : {}),
            ...(typeof error.retryAfterMs === 'number' && Number.isFinite(error.retryAfterMs)
                ? { retryAfterMs: Math.max(0, Math.floor(error.retryAfterMs)) } : {}),
            ...(typeof error.resumeCheckpointId === 'string' ? { resumeCheckpointId: error.resumeCheckpointId.slice(0, 200) } : {})
        } : undefined;
        const interrupted = status === 'running';
        const recoveredError: DesktopAgentRunFailure | undefined = interrupted ? {
            code: 'AGENT_RUN_INTERRUPTED',
            message: 'Agent run was interrupted because the application closed before it finished.',
            kind: 'failed',
            retryable: false,
            resumable: Boolean(normalizedError?.resumeCheckpointId),
            ...(normalizedError?.resumeCheckpointId ? { resumeCheckpointId: normalizedError.resumeCheckpointId } : {})
        } : normalizedError;
        const suppliedFinishedAt = typeof candidate.finishedAt === 'number' && Number.isFinite(candidate.finishedAt)
            ? Math.max(startedAt, candidate.finishedAt) : undefined;
        return {
            childRunId,
            parentRunId,
            rootRunId,
            depth,
            task: typeof candidate.task === 'string' ? candidate.task.slice(0, 20_000) : '',
            ...(typeof candidate.role === 'string' && candidate.role.trim()
                ? { role: candidate.role.trim().slice(0, 64) as DesktopAgentChildSnapshot['role'] } : {}),
            ...(typeof candidate.slotId === 'string' && candidate.slotId.trim()
                ? { slotId: candidate.slotId.trim().slice(0, 120) } : {}),
            ...(Array.isArray(candidate.acceptanceCriteria)
                ? { acceptanceCriteria: candidate.acceptanceCriteria.filter((item): item is string => typeof item === 'string').slice(0, 12).map(item => item.slice(0, 600)) } : {}),
            ...((source => source ? { routeSource: source } : {})(normalizeCouncilRouteSource(candidate.routeSource))),
            ...(typeof candidate.invocationKey === 'string' && candidate.invocationKey.trim()
                ? { invocationKey: candidate.invocationKey.trim().slice(0, 128) } : {}),
            status: interrupted ? 'interrupted' : status,
            events,
            eventCount,
            firstEventIndex,
            nextEventIndex,
            startedAt,
            updatedAt,
            ...(interrupted || suppliedFinishedAt !== undefined
                ? { finishedAt: Math.max(startedAt, updatedAt, suppliedFinishedAt || 0) } : {}),
            taskContext: context,
            ...(receipt ? { receipt } : {}),
            ...(result && typeof result.runId === 'string' && typeof result.finalText === 'string' ? {
                result: {
                    runId: result.runId.slice(0, 200),
                    status: (['completed', 'limit_reached', 'cancelled', 'paused'].includes(String(result.status))
                        ? result.status : 'completed') as AgentRunStatus,
                    finalText: result.finalText.slice(0, 20_000),
                    finalMessage: normalizeRuntimeFinalMessage(result.finalMessage),
                    citations: normalizeModelCitations(result.citations),
                    usage: {
                        inputTokens: finiteNonNegativeInteger((result.usage as Record<string, unknown> | undefined)?.inputTokens),
                        outputTokens: finiteNonNegativeInteger((result.usage as Record<string, unknown> | undefined)?.outputTokens)
                    },
                    turns: finiteNonNegativeInteger(result.turns),
                    toolCalls: finiteNonNegativeInteger(result.toolCalls),
                    stopReason: (typeof result.stopReason === 'string' && result.stopReason.length <= 80
                        ? result.stopReason
                        : result.status === 'cancelled' ? 'cancel_requested'
                            : result.status === 'paused' ? 'pause_requested'
                                : result.status === 'limit_reached' ? 'turn_limit_reached' : 'completed') as AgentRunResult['stopReason'],
                    ...(typeof result.resumeCheckpointId === 'string' && result.resumeCheckpointId.length <= 200
                        ? { resumeCheckpointId: result.resumeCheckpointId.slice(0, 200) } : {}),
                    ...(normalizeAgentChildReceipt(result.receipt)
                        ? { receipt: normalizeAgentChildReceipt(result.receipt) } : {}),
                    ...(result.checkpointError && typeof result.checkpointError === 'object' && !Array.isArray(result.checkpointError)
                        && typeof (result.checkpointError as Record<string, unknown>).code === 'string'
                        && typeof (result.checkpointError as Record<string, unknown>).message === 'string' ? {
                            checkpointError: {
                                code: String((result.checkpointError as Record<string, unknown>).code).slice(0, 200),
                                message: String((result.checkpointError as Record<string, unknown>).message).slice(0, 2_000)
                            }
                        } : {})
                }
            } : {}),
            ...(recoveredError ? { error: recoveredError } : {}),
            ...(candidate.checkpointError && typeof candidate.checkpointError === 'object' && !Array.isArray(candidate.checkpointError)
                && typeof (candidate.checkpointError as Record<string, unknown>).code === 'string'
                && typeof (candidate.checkpointError as Record<string, unknown>).message === 'string' ? {
                    checkpointError: {
                        code: String((candidate.checkpointError as Record<string, unknown>).code).slice(0, 200),
                        message: String((candidate.checkpointError as Record<string, unknown>).message).slice(0, 2_000)
                    }
                } : {})
        };
    });
}

