/** A JPEG thumbnail (longest side 320 px) of an image as a data URL, for a message's history. */
async function imageThumbnailDataUrl(mimeType: string, dataBase64: string): Promise<string | undefined> {
    if (typeof createImageBitmap !== 'function' || typeof OffscreenCanvas !== 'function') return undefined;
    const bytes = Uint8Array.from(atob(dataBase64), character => character.charCodeAt(0));
    const bitmap = await createImageBitmap(new Blob([bytes], { type: mimeType }));
    try {
        const scale = Math.min(1, 320 / Math.max(bitmap.width, bitmap.height));
        const canvas = new OffscreenCanvas(Math.max(1, Math.round(bitmap.width * scale)), Math.max(1, Math.round(bitmap.height * scale)));
        const context = canvas.getContext('2d');
        if (!context) return undefined;
        context.fillStyle = '#fff';
        context.fillRect(0, 0, canvas.width, canvas.height);
        context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
        const blob = await canvas.convertToBlob({ type: 'image/jpeg', quality: 0.72 });
        const buffer = new Uint8Array(await blob.arrayBuffer());
        let binary = '';
        for (let index = 0; index < buffer.length; index += 0x8000) binary += String.fromCharCode(...buffer.subarray(index, index + 0x8000));
        const url = `data:image/jpeg;base64,${btoa(binary)}`;
        return url.length <= 60_000 ? url : undefined;
    } finally {
        bitmap.close();
    }
}

