type CodingGoalStatus = 'active' | 'paused' | 'completed';

interface CodingGoalRecord {
    readonly id: string;
    readonly prompt: string;
    readonly status: CodingGoalStatus;
    readonly createdAt: number;
    readonly updatedAt: number;
    readonly attempts: number;
    readonly lastRunAt?: number;
    readonly pausedAt?: number;
    readonly activeTimePauses?: readonly { readonly start: number; readonly end: number }[];
    /** Spending limits the user raised by continuing past one (GOAL_SPEND_BUDGET_MICROS / GOAL_TOKEN_BUDGET until then). */
    readonly budgetMicros?: number;
    readonly budgetTokens?: number;
}

/**
 * The markdown copy in a project is a recovery record, not a transcript. Keep
 * a small machine-readable header so a session mirror can be rebuilt after a
 * renderer/profile reset without guessing which conversation owns a goal.
 */
interface PersistedCodingGoalFile {
    readonly conversationId: string;
    readonly goalId: string;
    readonly prompt: string;
    readonly status: CodingGoalStatus;
    readonly createdAt: number;
    readonly updatedAt: number;
    readonly attempts: number;
    readonly lastRunAt?: number;
    readonly pausedAt?: number;
    readonly activeTimePauses?: readonly { readonly start: number; readonly end: number }[];
    readonly budgetMicros?: number;
    readonly budgetTokens?: number;
}

function parsePersistedCodingGoalFile(text: string): PersistedCodingGoalFile | undefined {
    const normalized = String(text || '').replace(/\r\n?/g, '\n');
    const header = /^---\n([\s\S]*?)\n---\n/.exec(normalized);
    if (!header) return undefined;
    const fields = new Map<string, string>();
    for (const line of header[1].split('\n')) {
        const match = /^([A-Za-z][A-Za-z0-9]*):\s*(.*)$/.exec(line.trim());
        if (match) fields.set(match[1], match[2].trim());
    }
    const conversationId = fields.get('conversationId') || '';
    const goalId = fields.get('goalId') || '';
    // The serializer writes a heading/status section before the prompt. The
    // prompt is the final section and may itself contain Markdown headings.
    const prompt = goalFileObjective(normalized.slice(header[0].length));
    const status = fields.get('status');
    const createdAt = Number(fields.get('createdAt'));
    const updatedAt = Number(fields.get('updatedAt'));
    const attempts = Number(fields.get('attempts'));
    const lastRunAt = Number(fields.get('lastRunAt'));
    const budgetMicros = Number(fields.get('budgetMicros')), budgetTokens = Number(fields.get('budgetTokens'));
    if (!conversationId || !goalId || !prompt || !Number.isFinite(createdAt) || !Number.isFinite(updatedAt)
        || !Number.isSafeInteger(attempts) || attempts < 0
        || (status !== 'active' && status !== 'paused' && status !== 'completed')) return undefined;
    return {
        conversationId,
        goalId,
        prompt: prompt.slice(0, 200_000),
        status,
        createdAt: Math.max(0, createdAt),
        updatedAt: Math.max(0, updatedAt),
        attempts,
        ...normalizeGoalTiming({ pausedAt: fields.has('pausedAt') ? Number(fields.get('pausedAt')) : undefined,
            activeTimePauses: (() => { try { return JSON.parse(fields.get('activeTimePauses') || '[]'); } catch { return []; } })() }),
        ...(Number.isFinite(lastRunAt) && lastRunAt >= 0 ? { lastRunAt } : {}),
        // Raised spending limits: positive whole numbers only, anything else falls back to the defaults.
        ...(Number.isSafeInteger(budgetMicros) && budgetMicros > 0 ? { budgetMicros } : {}),
        ...(Number.isSafeInteger(budgetTokens) && budgetTokens > 0 ? { budgetTokens } : {})
    };
}

