interface CodingWorkspaceBinding {
    readonly id: string;
    readonly path: string;
    readonly kind?: 'project' | 'selected' | 'private';
    readonly status?: 'available' | 'missing' | 'moved' | 'unlinked';
    readonly permission?: AgentPermissionMode;
}

function normalizeCodingWorkspaceBindings(value: unknown): readonly CodingWorkspaceBinding[] | undefined {
    if (!Array.isArray(value)) return undefined;
    const seen = new Set<string>();
    const bindings = value.filter((candidate): candidate is Record<string, unknown> => Boolean(
        candidate && typeof candidate === 'object' && !Array.isArray(candidate)
    )).map((candidate, index): CodingWorkspaceBinding | undefined => {
        // Retain only a private layout's logical preferences. Its absolute
        // path is reconstructed from the host-owned layout before use.
        if (candidate.kind === 'private') {
            if (typeof candidate.id !== 'string' || !/^private-(?:0|[1-9]\d*)$/.test(candidate.id) || seen.has(candidate.id)) return undefined;
            seen.add(candidate.id);
            return { id: candidate.id, path: '', kind: 'private', status: candidate.status === 'unlinked' ? 'unlinked' : 'available',
                ...(candidate.permission === 'read_only' || candidate.permission === 'workspace_write' || candidate.permission === 'full_access'
                    ? { permission: candidate.permission } : {}) };
        }
        const path = typeof candidate.path === 'string' ? candidate.path.trim().slice(0, 32_768) : '';
        if (!path || /[\r\n\0]/.test(path)) return undefined;
        const id = typeof candidate.id === 'string' && /^[A-Za-z0-9._:-]{1,160}$/.test(candidate.id.trim())
            ? candidate.id.trim() : `workspace-${index + 1}`;
        if (seen.has(id)) return undefined;
        seen.add(id);
        const kind = candidate.kind === 'project' || candidate.kind === 'selected' || candidate.kind === 'private'
            ? candidate.kind : undefined;
        const status = candidate.status === 'available' || candidate.status === 'missing'
            || candidate.status === 'moved' || candidate.status === 'unlinked' ? candidate.status : undefined;
        const permission = candidate.permission === 'read_only' || candidate.permission === 'workspace_write'
            || candidate.permission === 'full_access' ? candidate.permission : undefined;
        return { id, path, ...(kind ? { kind } : {}), ...(status ? { status } : {}), ...(permission ? { permission } : {}) };
    }).filter((binding): binding is CodingWorkspaceBinding => Boolean(binding));
    return bindings.length ? bindings.slice(0, 32) : undefined;
}

