const NEXTMUX_TERMINAL_FONT_FAMILY = 'ui-monospace, "SFMono-Regular", "SF Mono", Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", "PingFang SC", "Microsoft YaHei UI", monospace';

interface NextMuxNativeClipboardBridge {
    readonly readClipboard?: () => Promise<string> | string;
    readonly writeClipboard?: (value: string) => Promise<void> | void;
}

function nativeClipboardBridge(): NextMuxNativeClipboardBridge | undefined {
    // Electron's contextBridge publishes this object on the renderer window.
    // Read it from `window` explicitly: some Electron/Monaco bundles provide a
    // separate `globalThis` shim, which can otherwise hide contextBridge APIs.
    if (typeof window === 'undefined') return undefined;
    return (window as Window & { readonly electronTheiaCore?: NextMuxNativeClipboardBridge }).electronTheiaCore;
}

/**
 * Title-bar Edit commands are dispatched outside the focused DOM control.  In
 * an Electron window the browser Clipboard API can be denied while the native
 * clipboard remains available through the preload bridge, so use that bridge
 * for the same operations as the terminal surfaces.  The Theia service stays
 * as the browser/test fallback.
 */
async function writeDesktopClipboard(clipboardService: ClipboardService, value: string): Promise<void> {
    const nativeClipboard = nativeClipboardBridge();
    if (nativeClipboard?.writeClipboard) {
        await nativeClipboard.writeClipboard(value);
        return;
    }
    await clipboardService.writeText(value);
}

async function readDesktopClipboard(clipboardService: ClipboardService): Promise<string> {
    const nativeClipboard = nativeClipboardBridge();
    if (nativeClipboard?.readClipboard) return await nativeClipboard.readClipboard();
    return await clipboardService.readText();
}

function currentTerminalPlatform(): NextMuxTerminalPlatform {
    const platform = OS.type();
    if (platform === OS.Type.Windows) return 'windows';
    if (platform === OS.Type.OSX) return 'macos';
    return 'linux';
}

/**
 * xterm parses writes asynchronously. Disposing it while the final write or
 * viewport refresh is still queued can leave a renderer callback pointing at
 * services that have already been torn down. Drain the write queue and two
 * paint frames before disposal; the timeout is only a bounded fallback for a
 * hidden document where animation frames are suspended.
 */
function disposeXtermAfterWrites(terminal: XtermTerminal): void {
    let disposed = false;
    const dispose = (): void => {
        if (disposed) return;
        disposed = true;
        try { terminal.dispose(); } catch { /* The terminal may already be owned by a closing page. */ }
    };
    const afterPaint = (): void => {
        requestAnimationFrame(() => requestAnimationFrame(dispose));
    };
    try {
        terminal.write('', afterPaint);
    } catch {
        afterPaint();
    }
    window.setTimeout(dispose, 500);
}

class NextMuxTerminalHost extends React.PureComponent<{
    readonly terminal?: TerminalWidget;
    readonly theme: NextMuxTerminalAppearance;
    readonly clipboardService: ClipboardService;
}> {
    protected host: HTMLDivElement | null = null;
    protected resizeObserver: ResizeObserver | undefined;
    protected layoutFrame = 0;

    override componentDidMount(): void {
        this.attachTerminal();
        this.applyTerminalTheme();
        if (this.host) {
            this.resizeObserver = new ResizeObserver(() => {
                // The owning widget performs one synchronous fit per pointer
                // frame while a pane is being dragged. Scheduling a second fit
                // here makes xterm trail the divider and doubles layout work.
                if (document.documentElement.classList.contains('nmx-pane-resizing-x')
                    || document.documentElement.classList.contains('nmx-pane-resizing-y')
                    || this.host?.closest('.nmx-terminal-drawer.is-closed, .nmx-terminal-drawer.is-transitioning')) return;
                this.scheduleTerminalFit();
            });
            this.resizeObserver.observe(this.host);
        }
    }

    override componentDidUpdate(previous: Readonly<{ readonly terminal?: TerminalWidget; readonly theme: NextMuxTerminalAppearance }>): void {
        if (previous.terminal !== this.props.terminal) {
            this.detachTerminal(previous.terminal);
            this.attachTerminal();
        }
        if (previous.terminal !== this.props.terminal || previous.theme !== this.props.theme) {
            this.applyTerminalTheme();
            this.scheduleTerminalFit();
        }
    }

    override componentWillUnmount(): void {
        this.resizeObserver?.disconnect();
        this.resizeObserver = undefined;
        if (this.layoutFrame) cancelAnimationFrame(this.layoutFrame);
        this.layoutFrame = 0;
        this.detachTerminal(this.props.terminal);
    }

    protected scheduleTerminalFit(): void {
        if (this.layoutFrame) return;
        this.layoutFrame = requestAnimationFrame(() => {
            this.layoutFrame = 0;
            const terminal = this.props.terminal;
            if (!terminal || terminal.isDisposed || terminal.node.parentElement !== this.host
                || this.host?.closest('.nmx-terminal-drawer.is-closed, .nmx-terminal-drawer.is-transitioning')) return;
            terminal.update();
            this.applyTerminalTheme();
            const xterm = (terminal as TerminalWidget & {
                getTerminal?: () => { element?: HTMLElement | null };
            }).getTerminal?.();
            if (!xterm?.element?.isConnected) return;
            const resizeTerminal = (terminal as TerminalWidget & {
                resizeTerminal?: (() => void) & { cancel?: () => void };
            }).resizeTerminal;
            resizeTerminal?.call(terminal);
        });
    }

    protected attachTerminal(): void {
        const terminal = this.props.terminal;
        if (!terminal || !this.host || terminal.isDisposed) return;
        if (terminal.node.parentElement === this.host && terminal.isAttached) {
            this.scheduleTerminalFit();
            return;
        }
        if (terminal.isAttached) UnsafeWidgetUtilities.detach(terminal);
        terminal.node.remove();
        UnsafeWidgetUtilities.attach(terminal, this.host);
        this.applyTerminalTheme();
        this.scheduleTerminalFit();
        requestAnimationFrame(() => {
            if (!terminal.isDisposed && terminal.node.parentElement === this.host) {
                terminal.activate();
                this.applyTerminalTheme();
                this.scheduleTerminalFit();
            }
        });
    }

    protected detachTerminal(terminal: TerminalWidget | undefined): void {
        if (!terminal || terminal.isDisposed || terminal.node.parentElement !== this.host) return;
        const resizeTerminal = (terminal as TerminalWidget & {
            resizeTerminal?: (() => void) & { cancel?: () => void };
        }).resizeTerminal;
        resizeTerminal?.cancel?.();
        if (terminal.isAttached) UnsafeWidgetUtilities.detach(terminal);
        else terminal.node.remove();
    }

    protected applyTerminalTheme(): void {
        const terminal = this.props.terminal;
        if (!terminal || terminal.isDisposed) return;
        const xterm = (terminal as TerminalWidget & {
            getTerminal?: () => {
                element?: HTMLElement | null;
                options: { scrollback?: number; theme?: Readonly<Record<string, string>>; fontFamily?: string; letterSpacing?: number };
            };
        }).getTerminal?.();
        if (xterm?.element?.isConnected) {
            xterm.options.scrollback = NEXTMUX_TERMINAL_SCROLLBACK_LINES;
            xterm.options.theme = { ...NEXTMUX_TERMINAL_THEMES[this.props.theme] };
            xterm.options.fontFamily = NEXTMUX_TERMINAL_FONT_FAMILY;
            // Theia's default 1px letter spacing makes shells look sparse next to the AI command log.
            if (xterm.options.letterSpacing !== 0) xterm.options.letterSpacing = 0;
            terminal.node.dataset.nextmuxScrollbackLines = String(xterm.options.scrollback);
            terminal.node.dataset.nextmuxFontFamily = NEXTMUX_TERMINAL_FONT_FAMILY;
        }
        terminal.node.dataset.nextmuxTheme = this.props.theme;
    }

    protected setHost = (host: HTMLDivElement | null): void => {
        this.host = host;
    };

    protected handleTerminalKeyDown = (event: React.KeyboardEvent<HTMLDivElement>): void => {
        const terminal = this.props.terminal;
        if (event.key !== 'Enter' || !terminal || terminal.isDisposed || !terminal.hasSelection()) return;
        const selection = terminal.getSelection();
        if (!selection) return;
        event.preventDefault();
        event.stopPropagation();
        event.nativeEvent.stopImmediatePropagation();
        const nativeClipboard = nativeClipboardBridge();
        void Promise.resolve(nativeClipboard?.writeClipboard
            ? nativeClipboard.writeClipboard(selection)
            : this.props.clipboardService.writeText(selection)).catch(() => undefined);
        const xterm = (terminal as TerminalWidget & {
            getTerminal?: () => { clearSelection?: () => void };
        }).getTerminal?.();
        xterm?.clearSelection?.();
    };

    protected handleTerminalContextMenu = (event: React.MouseEvent<HTMLDivElement>): void => {
        const terminal = this.props.terminal;
        if (!terminal || terminal.isDisposed) return;
        event.preventDefault();
        event.stopPropagation();
        const nativeClipboard = nativeClipboardBridge();
        void Promise.resolve(nativeClipboard?.readClipboard
            ? nativeClipboard.readClipboard()
            : this.props.clipboardService.readText()).then(text => {
            if (!text || terminal.isDisposed || terminal !== this.props.terminal) return;
            terminal.paste(text);
            terminal.activate();
        }).catch(() => undefined);
    };

    override render(): React.ReactNode {
        return <div className='nmx-terminal-host' ref={this.setHost}
            onKeyDownCapture={this.handleTerminalKeyDown}
            onContextMenuCapture={this.handleTerminalContextMenu}></div>;
    }
}

class NextMuxCommandOutputHost extends React.PureComponent<{
    readonly commandLine: string;
    readonly output: string;
    readonly running: boolean;
    readonly theme: NextMuxTerminalAppearance;
    readonly clipboardService: ClipboardService;
    /** Fill the parent (terminal drawer log) instead of sizing to the output inside a conversation row. */
    readonly fill?: boolean;
    readonly label?: string;
}> {
    protected host: HTMLDivElement | null = null;
    protected terminal: XtermTerminal | undefined;
    protected fitAddon: FitAddon | undefined;
    protected resizeObserver: ResizeObserver | undefined;
    protected mountFrame = 0;
    protected layoutFrame = 0;
    protected lastWidth = 0;
    protected lastHeight = 0;
    protected renderedCommand = '';
    protected renderedOutput = '';

    protected terminalBackground(): string {
        if (this.props.fill) return NEXTMUX_TERMINAL_THEMES[this.props.theme].background;
        return this.props.theme === 'light' ? '#ecebe8' : '#19181a';
    }

    override componentDidMount(): void {
        if (!this.host || !this.props.fill && !this.props.output && !this.props.running) return;
        if (this.props.fill) {
            this.initTerminal();
            return;
        }
        this.mountFrame = requestAnimationFrame(() => {
            this.mountFrame = 0;
            this.initTerminal();
        });
    }

    protected initTerminal(): void {
        if (!this.host || this.terminal || !this.host.isConnected
            || !this.props.fill && !this.props.output && !this.props.running) return;
        this.terminal = new XtermTerminal({
            allowTransparency: false,
            convertEol: true,
            cursorBlink: this.props.running,
            cursorInactiveStyle: this.props.running ? 'outline' : 'none',
            cursorStyle: 'block',
            disableStdin: true,
            fontFamily: NEXTMUX_TERMINAL_FONT_FAMILY,
            fontSize: 12.5,
            lineHeight: 1.22,
            scrollback: NEXTMUX_TERMINAL_SCROLLBACK_LINES,
            theme: { ...NEXTMUX_TERMINAL_THEMES[this.props.theme], background: this.terminalBackground() }
        });
        this.fitAddon = new FitAddon();
        this.terminal.loadAddon(this.fitAddon);
        this.terminal.open(this.host);
        this.host.dataset.nextmuxScrollbackLines = String(this.terminal.options.scrollback);
        this.terminal.attachCustomKeyEventHandler(event => {
            const terminal = this.terminal;
            if (!terminal) return true;
            const action = terminalShortcutAction(event, currentTerminalPlatform(), terminal.hasSelection());
            if (action !== 'copy') return true;
            const selection = terminal.getSelection();
            if (selection) {
                const nativeClipboard = nativeClipboardBridge();
                void Promise.resolve(nativeClipboard?.writeClipboard
                    ? nativeClipboard.writeClipboard(selection)
                    : this.props.clipboardService.writeText(selection)).catch(() => undefined);
                terminal.clearSelection();
            }
            return false;
        });
        this.resizeObserver = new ResizeObserver(entries => {
            const rect = entries[0]?.contentRect;
            if (rect) {
                const width = Math.round(rect.width);
                const height = Math.round(rect.height);
                if (width === this.lastWidth && (!this.props.fill || height === this.lastHeight)) return;
                this.lastWidth = width;
                this.lastHeight = height;
            }
            this.scheduleFit();
        });
        this.lastWidth = Math.round(this.host.clientWidth);
        this.lastHeight = Math.round(this.host.clientHeight);
        this.resizeObserver.observe(this.host);
        this.syncTerminal(true);
        this.scheduleFit();
    }

    override componentDidUpdate(previous: Readonly<{
        readonly commandLine: string;
        readonly output: string;
        readonly running: boolean;
        readonly theme: NextMuxTerminalAppearance;
    }>): void {
        if (!this.terminal) {
            if (this.props.fill || this.props.output || this.props.running) this.initTerminal();
            return;
        }
        if (previous.theme !== this.props.theme) this.terminal.options.theme = { ...NEXTMUX_TERMINAL_THEMES[this.props.theme], background: this.terminalBackground() };
        if (previous.running !== this.props.running) {
            this.terminal.options.cursorBlink = this.props.running;
            this.terminal.options.cursorInactiveStyle = this.props.running ? 'outline' : 'none';
        }
        this.syncTerminal(false);
        this.scheduleFit();
    }

    override componentWillUnmount(): void {
        this.resizeObserver?.disconnect();
        this.resizeObserver = undefined;
        if (this.mountFrame) cancelAnimationFrame(this.mountFrame);
        this.mountFrame = 0;
        if (this.layoutFrame) cancelAnimationFrame(this.layoutFrame);
        this.layoutFrame = 0;
        const terminal = this.terminal;
        this.terminal = undefined;
        this.fitAddon = undefined;
        if (terminal) disposeXtermAfterWrites(terminal);
    }

    protected terminalCommand(value: string): string {
        return value.replace(/[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g, '').slice(0, 8_000);
    }

    protected syncTerminal(forceReplay: boolean): void {
        const terminal = this.terminal;
        if (!terminal) return;
        const followOutput = terminal.buffer.active.baseY - terminal.buffer.active.viewportY <= 1;
        const replay = forceReplay || this.renderedCommand !== this.props.commandLine
            || !this.props.output.startsWith(this.renderedOutput);
        if (replay) {
            terminal.reset();
            terminal.options.theme = { ...NEXTMUX_TERMINAL_THEMES[this.props.theme], background: this.terminalBackground() };
            if (this.props.output) terminal.write(this.props.output);
        } else if (this.props.output.length > this.renderedOutput.length) {
            terminal.write(this.props.output.slice(this.renderedOutput.length));
        }
        terminal.write('', () => this.syncScrollable());
        this.renderedCommand = this.props.commandLine;
        this.renderedOutput = this.props.output;
        if (followOutput) requestAnimationFrame(() => this.terminal?.scrollToBottom());
    }

    protected syncScrollable(): void {
        if (!this.host || !this.terminal || !this.fitAddon || !this.host.isConnected) return;
        if (!this.props.fill) {
            const totalLines = this.terminal.rows + this.terminal.buffer.active.baseY;
            if (this.terminal.buffer.active.baseY > 0 && totalLines <= 9) {
                const expandedHeight = Math.min(180, totalLines * 16 + 14);
                if (this.host.offsetHeight < expandedHeight) {
                    this.host.style.height = `${expandedHeight}px`;
                    try { this.fitAddon.fit(); } catch { /* Ignore transient fit errors. */ }
                }
            }
        }
        const scrollable = this.terminal.buffer.active.baseY > 0;
        if (this.host.classList.contains('is-scrollable') !== scrollable) {
            this.host.classList.toggle('is-scrollable', scrollable);
            if (scrollable) {
                try { this.fitAddon.fit(); } catch { /* Ignore transient fit errors. */ }
            }
        }
    }

    protected scheduleFit(): void {
        if (this.layoutFrame || !this.terminal || !this.fitAddon) return;
        this.layoutFrame = requestAnimationFrame(() => {
            this.layoutFrame = 0;
            if (!this.host || !this.terminal || !this.fitAddon || !this.host.isConnected) return;
            try { this.fitAddon.fit(); } catch { /* A closing details element can briefly have zero size. */ }
            this.syncScrollable();
        });
    }

    protected handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>): void => {
        const terminal = this.terminal;
        if (event.key !== 'Enter' || !terminal?.hasSelection()) return;
        const selection = terminal.getSelection();
        if (!selection) return;
        event.preventDefault();
        event.stopPropagation();
        event.nativeEvent.stopImmediatePropagation();
        const nativeClipboard = nativeClipboardBridge();
        void Promise.resolve(nativeClipboard?.writeClipboard
            ? nativeClipboard.writeClipboard(selection)
            : this.props.clipboardService.writeText(selection)).catch(() => undefined);
        terminal.clearSelection();
    };

    protected setHost = (host: HTMLDivElement | null): void => {
        this.host = host;
    };

    override render(): React.ReactNode {
        const outputLines = this.props.output ? this.props.output.split(/\r?\n/).length : 1;
        const estimatedLines = Math.max(outputLines, Math.ceil((this.props.output?.length || 0) / 72));
        const height = Math.min(180, Math.max(54, Math.min(9, estimatedLines + 1) * 16 + 14));
        const commandLine = this.terminalCommand(this.props.commandLine);
        if (this.props.fill) {
            return <div className='nmx-agent-command-xterm is-fill' ref={this.setHost}
                aria-label={this.props.label || commandLine} aria-readonly='true' onKeyDownCapture={this.handleKeyDown}></div>;
        }
        return <>
            <div className='nmx-agent-command-line' title={commandLine} hidden={commandLine.length <= 240}>
                <i className='codicon codicon-terminal' aria-hidden='true'></i>
                <code data-nmx-literal>{commandLine}</code>
            </div>
            <div className='nmx-agent-command-xterm' hidden={!this.props.output && !this.props.running} style={{ height }} ref={this.setHost}
                aria-label={commandLine} aria-readonly='true' onKeyDownCapture={this.handleKeyDown}></div>
        </>;
    }
}

function ContextFileInlineRenameInput(props: {
    readonly name: string; readonly value: string; readonly label: string; readonly error: string; readonly busy: boolean;
    readonly onChange: (value: string) => void; readonly onSubmit: () => void; readonly onCancel: (restoreFocus: boolean) => void;
}): React.ReactElement {
    const input = React.useRef<HTMLInputElement>(null);
    React.useLayoutEffect(() => {
        if (!props.busy) input.current?.focus({ preventScroll: true });
    }, []);
    React.useLayoutEffect(() => {
        const extension = props.name.lastIndexOf('.');
        input.current?.setSelectionRange(0, extension > 0 ? extension : props.name.length);
    }, [props.name]);
    return <span className='nmx-context-file-inline-rename'>
        <input ref={input} data-nmx-literal value={props.value} aria-label={props.label} aria-invalid={Boolean(props.error)}
            title={props.error || props.label} disabled={props.busy} spellCheck={false}
            onChange={event => props.onChange(event.currentTarget.value)}
            onClick={event => event.stopPropagation()} onContextMenu={event => event.stopPropagation()}
            onBlur={() => {
                if (props.busy) return;
                if (props.value.trim() && props.value !== props.name) props.onSubmit();
                else props.onCancel(false);
            }}
            onKeyDown={event => {
                event.stopPropagation();
                if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229) return;
                if (event.key === 'Enter') { event.preventDefault(); if (!props.busy) props.onSubmit(); }
                else if (event.key === 'Escape') { event.preventDefault(); if (!props.busy) props.onCancel(true); }
            }} />
        {props.error && <small role='alert'>{props.error}</small>}
    </span>;
}

interface NextMuxFileEditorProps {
    readonly clipboardService: ClipboardService;
    readonly onClipboardError: (error: unknown) => void;
    readonly uri: string;
    readonly name: string;
    readonly content: string;
    readonly beforeContent?: string;
    readonly renderSideBySide?: boolean;
    readonly revision: number;
    readonly sourceRevision?: number;
    readonly recoveryKey?: string;
    readonly initialDrafts?: { readonly before?: string; readonly current?: string };
    readonly readOnly?: boolean;
    readonly largeFile?: boolean;
    readonly theme: 'light' | 'dark';
    readonly revealRange?: { readonly startLine: number; readonly endLine: number };
    readonly initialScrollPosition?: ContextFileScrollPosition;
    readonly onDirty: (dirty: boolean) => void;
    readonly onContentChange: (side: 'before' | 'current', content: string) => void;
    readonly onFocus: (side: 'before' | 'current') => void;
    readonly onSave: (side: 'before' | 'current', content: string) => void;
    readonly onScrollPositionChange?: (position: ContextFileScrollPosition) => void;
}

interface NextMuxCachedEditorModel {
    readonly model: monaco.editor.ITextModel;
    refs: number;
}

/**
 * Monaco owns undo/redo history on the text model, not on the editor widget.
 * Keep models alive while their file tab remains open so switching A → B → A
 * reattaches the same model (and its undo stack) instead of recreating it.
 */
const nextMuxEditorModelCache = new Map<string, NextMuxCachedEditorModel>();
const nextMuxOpenEditorUris = new Set<string>();

function acquireNextMuxEditorModel(key: string, content: string, language: string): { model: monaco.editor.ITextModel; reused: boolean } {
    const cached = nextMuxEditorModelCache.get(key);
    if (cached && !cached.model.isDisposed()) {
        cached.refs += 1;
        return { model: cached.model, reused: true };
    }
    const model = monaco.editor.createModel(content, language, monaco.Uri.parse(`inmemory://nextmux/${encodeURIComponent(key)}`));
    nextMuxEditorModelCache.set(key, { model, refs: 1 });
    return { model, reused: false };
}

function nextMuxEditorUriFromKey(key: string): string {
    const separator = key.lastIndexOf('::');
    return separator >= 0 ? key.slice(0, separator) : key;
}

function reconcileNextMuxEditorModelCache(openUris: readonly string[]): void {
    nextMuxOpenEditorUris.clear();
    openUris.forEach(uri => nextMuxOpenEditorUris.add(uri));
    for (const [key, cached] of nextMuxEditorModelCache) {
        if (cached.refs === 0 && !nextMuxOpenEditorUris.has(nextMuxEditorUriFromKey(key))) {
            cached.model.dispose();
            nextMuxEditorModelCache.delete(key);
        }
    }
}

function releaseNextMuxEditorModel(key: string): void {
    const cached = nextMuxEditorModelCache.get(key);
    if (!cached) return;
    cached.refs = Math.max(0, cached.refs - 1);
    if (cached.refs !== 0 || nextMuxOpenEditorUris.has(nextMuxEditorUriFromKey(key))) return;
    cached.model.dispose();
    nextMuxEditorModelCache.delete(key);
}

class NextMuxFileEditor extends React.PureComponent<NextMuxFileEditorProps> {
    protected host: HTMLDivElement | null = null;
    protected editor: monaco.editor.IStandaloneCodeEditor | monaco.editor.IStandaloneDiffEditor | undefined;
    protected models: monaco.editor.ITextModel[] = [];
    protected modelCacheKeys: string[] = [];
    protected newlyCreatedModelKeys = new Set<string>();
    protected disposables: monaco.IDisposable[] = [];
    protected fallbackDisposables: Array<() => void> = [];
    protected readonly dirtyBySide = new Map<'before' | 'current', boolean>();
    protected readonly baselineBySide = new Map<'before' | 'current', string>();
    protected revealAnimationFrame: number | undefined;
    protected scrollRestoreAnimationFrame: number | undefined;
    protected lastFocusedEditor: monaco.editor.IStandaloneCodeEditor | undefined;
    protected resizeObserver: ResizeObserver | undefined;
    protected layoutAnimationFrame: number | undefined;
    protected static themesRegistered = false;

    protected normalizeModelEol(text: string): string {
        return text.includes('\r') ? text.replace(/\r\n/g, '\n') : text;
    }

    protected registerThemes(): void {
        if (NextMuxFileEditor.themesRegistered) return;
        const tokenGroups = [
            ['comment'], ['keyword', 'storage', 'storage.modifier', 'tag', 'entity.name.tag', 'metatag', 'markup.heading'],
            ['storage.type', 'type', 'class', 'interface', 'function', 'identifier.function', 'support.function', 'entity.name.function', 'entity.name.type', 'entity.name.class', 'support.class', 'support.type'],
            ['string', 'attribute.value'], ['regexp'],
            ['string.escape', 'constant.character.escape', 'number', 'constant.numeric', 'constant.language', 'boolean', 'attribute.name', 'entity.other.attribute-name'],
            ['constant', 'variable', 'variable.other', 'variable.property', 'property', 'meta.object-literal.key', 'key'],
            ['operator', 'keyword.operator', 'delimiter', 'punctuation', 'variable.parameter', 'support.type.property-name', 'string.key.json']
        ];
        const themes = [
            { name: 'nextmux-codex-dark', base: 'vs-dark' as const, background: '#181818',
                foregrounds: ['999999', 'F67576', 'B06DFF', '85DF7B', '3D8DFF', '6DCBF4', 'FA994C', '999999'],
                foreground: '#FCFCFC', lineNumber: '#5C5C5C', activeLineNumber: '#A0A0A0', lineHighlight: '#ffffff0a', selection: '#0169cc59' },
            { name: 'nextmux-codex-light', base: 'vs' as const, background: '#f9f9f9',
                foregrounds: ['666666', 'D53538', '751ED9', '008809', '001BCB', '0071EA', 'BD5800', '666666'],
                foreground: '#0D0D0D', lineNumber: '#A8A8A8', activeLineNumber: '#4F4F4F', lineHighlight: '#0000000a', selection: '#0169cc33' }
        ];
        for (const theme of themes) monaco.editor.defineTheme(theme.name, {
            base: theme.base, inherit: true,
            rules: tokenGroups.flatMap((tokens, index) => tokens.map(token => ({ token, foreground: theme.foregrounds[index] }))),
            colors: { 'editor.background': theme.background, 'editorGutter.background': theme.background,
                'editor.foreground': theme.foreground, 'editorLineNumber.foreground': theme.lineNumber,
                'editorLineNumber.activeForeground': theme.activeLineNumber, 'editor.lineHighlightBackground': theme.lineHighlight,
                'editor.selectionBackground': theme.selection }
        });
        NextMuxFileEditor.themesRegistered = true;
    }

    protected observeEditorLayout(): void {
        if (!this.host || !this.editor) return;
        this.resizeObserver?.disconnect();
        this.resizeObserver = new ResizeObserver(() => {
            if (this.layoutAnimationFrame !== undefined) window.cancelAnimationFrame(this.layoutAnimationFrame);
            this.layoutAnimationFrame = window.requestAnimationFrame(() => {
                this.layoutAnimationFrame = undefined;
                this.editor?.layout();
            });
        });
        this.resizeObserver.observe(this.host);
        this.editor.layout();
    }

    protected commandEditor(): monaco.editor.IStandaloneCodeEditor | undefined {
        if (!this.editor) return undefined;
        if ('getModifiedEditor' in this.editor) {
            const candidates = [this.editor.getModifiedEditor(), this.editor.getOriginalEditor()];
            return candidates.find(candidate => candidate.hasTextFocus()) || this.lastFocusedEditor || candidates[0];
        }
        return this.editor;
    }

    canRunEditingCommand(command: DesktopEditCommand): boolean {
        if (this.props.readOnly && command !== 'copy') return false;
        const editor = this.commandEditor();
        const model = editor?.getModel();
        if (!editor || !model) return false;
        if (command === 'undo') return model.canUndo();
        if (command === 'redo') return model.canRedo();
        if (command === 'paste') return true;
        if (command === 'selectAll') return model.getValueLength() > 0;
        return !editor.getSelection()?.isEmpty();
    }

    async runEditingCommand(command: DesktopEditCommand): Promise<void> {
        if (this.props.readOnly && command !== 'copy') return;
        const editor = this.commandEditor();
        const model = editor?.getModel();
        if (!editor || !model) return;
        editor.focus();
        if (command === 'undo') void model.undo();
        else if (command === 'redo') void model.redo();
        else if (command === 'selectAll') editor.trigger('nextmux-title-menu', 'editor.action.selectAll', null);
        else {
            const selection = editor.getSelection();
            if (!selection) return;
            const version = model.getVersionId();
            const text = command === 'paste' ? await readDesktopClipboard(this.props.clipboardService) : '';
            if (command === 'copy' || command === 'cut') {
                await writeDesktopClipboard(this.props.clipboardService, model.getValueInRange(selection));
                if (command === 'copy') return;
            }
            // Clipboard IPC is asynchronous. Never apply its result to a
            // switched tab, changed selection, or newer file contents.
            if (model.isDisposed() || editor.getModel() !== model || model.getVersionId() !== version
                || !editor.getSelection()?.equalsSelection(selection)) return;
            model.pushStackElement();
            editor.executeEdits('nextmux-clipboard', [{ range: selection, text, forceMoveMarkers: true }]);
            model.pushStackElement();
        }
    }

    applyHistoryContent(content: string): void {
        if (this.props.readOnly) return;
        const editor = this.editor && 'getModifiedEditor' in this.editor ? this.editor.getModifiedEditor() : this.editor;
        const model = editor?.getModel();
        if (editor && model) {
            if (model.getValue() !== content) {
                model.pushStackElement();
                editor.executeEdits('nextmux-file-history', [{ range: model.getFullModelRange(), text: content, forceMoveMarkers: true }]);
                model.pushStackElement();
            }
            editor.focus();
            return;
        }
        const textarea = this.host?.querySelector<HTMLTextAreaElement>('textarea:last-child');
        if (textarea && textarea.value !== content) {
            textarea.value = content;
            textarea.dispatchEvent(new Event('input', { bubbles: true }));
        }
    }

    override componentDidMount(): void {
        this.createEditorSafely();
        this.scheduleInitialScrollPosition();
        this.scheduleRevealRange();
    }

    override componentDidUpdate(previous: Readonly<NextMuxFileEditorProps>): void {
        this.host?.classList.toggle('is-inline-current', this.props.beforeContent !== undefined && !Boolean(this.props.renderSideBySide));
        if (this.editor && 'getModifiedEditor' in this.editor) {
            this.editor.updateOptions({ renderSideBySide: Boolean(this.props.renderSideBySide),
                renderOverviewRuler: Boolean(this.props.renderSideBySide), renderMarginRevertIcon: false });
            this.editor.getOriginalEditor().updateOptions({ lineNumbers: this.props.renderSideBySide ? 'on' : 'off',
                lineNumbersMinChars: this.props.renderSideBySide ? this.lineNumbersMinChars() : 0,
                glyphMargin: false, folding: false, lineDecorationsWidth: this.props.renderSideBySide ? 4 : 0 });
            this.editor.getModifiedEditor().updateOptions({ lineNumbers: 'on', lineNumbersMinChars: this.lineNumbersMinChars(),
                glyphMargin: false, folding: false, lineDecorationsWidth: 4,
                minimap: { enabled: !Boolean(this.props.largeFile), autohide: 'none', side: 'right', showSlider: 'mouseover', renderCharacters: true, maxColumn: 80, scale: 1 } });
        } else if (this.editor && previous.content !== this.props.content) {
            this.editor.updateOptions({ lineNumbersMinChars: this.lineNumbersMinChars(), glyphMargin: false, folding: false, lineDecorationsWidth: 4 });
        }
        if (previous.uri !== this.props.uri || previous.recoveryKey !== this.props.recoveryKey) {
            this.disposeEditor();
            this.createEditorSafely();
            this.scheduleInitialScrollPosition();
            this.scheduleRevealRange();
            return;
        }
        if (previous.theme !== this.props.theme) {
            monaco.editor.setTheme(this.props.theme === 'light' ? 'nextmux-codex-light' : 'nextmux-codex-dark');
        }
        if (previous.readOnly !== this.props.readOnly) {
            this.editor?.updateOptions({ readOnly: Boolean(this.props.readOnly) });
            if (this.editor && 'getModifiedEditor' in this.editor) this.editor.updateOptions({ originalEditable: !this.props.readOnly });
            this.host?.querySelectorAll('textarea').forEach(textarea => { textarea.readOnly = Boolean(this.props.readOnly); });
        }
        const wasDiff = previous.beforeContent !== undefined;
        const isDiff = this.props.beforeContent !== undefined;
        if (wasDiff && !isDiff && this.editor && 'getModifiedEditor' in this.editor) {
            this.collapseDiffEditorPreservingHistory();
            return;
        }
        if (wasDiff !== isDiff) {
            this.disposeEditor();
            this.createEditorSafely();
            return;
        }
        if (previous.sourceRevision !== this.props.sourceRevision) {
            this.acceptRefreshedSource(previous);
        }
        if (previous.revision !== this.props.revision) {
            this.acceptSavedRevision();
        }
        if (previous.revealRange?.startLine !== this.props.revealRange?.startLine
            || previous.revealRange?.endLine !== this.props.revealRange?.endLine) {
            this.scheduleRevealRange();
        }
        if (previous.initialScrollPosition?.top !== this.props.initialScrollPosition?.top
            || previous.initialScrollPosition?.left !== this.props.initialScrollPosition?.left) {
            this.scheduleInitialScrollPosition();
        }
    }

    override componentWillUnmount(): void {
        this.disposeEditor();
    }

    protected language(): string {
        const language = editorLanguageForName(this.props.name);
        ensureEditorLanguage(language);
        return language;
    }

    protected lineNumbersMinChars(): number {
        const countLines = (content: string): number => {
            let count = 1;
            // Match Monaco's CRLF, CR and LF handling without splitting large files.
            for (let index = 0; index < content.length; index++) {
                const character = content.charCodeAt(index);
                if (character === 13) {
                    count++;
                    if (content.charCodeAt(index + 1) === 10) index++;
                } else if (character === 10) {
                    count++;
                }
            }
            return count;
        };
        const maxLineCount = Math.max(countLines(this.props.content),
            this.props.renderSideBySide && this.props.beforeContent !== undefined ? countLines(this.props.beforeContent) : 1);
        return Math.max(1, String(maxLineCount).length);
    }

    protected editorOptions(): monaco.editor.IStandaloneEditorConstructionOptions {
        const largeFile = Boolean(this.props.largeFile);
        return {
            automaticLayout: false,
            fontSize: 13,
            lineHeight: 20,
            fontFamily: 'ui-monospace, "SFMono-Regular", "SF Mono", Menlo, Consolas, "Liberation Mono", "PingFang SC", "Microsoft YaHei UI", monospace',
            fontLigatures: true,
            minimap: { enabled: !largeFile, autohide: 'none', side: 'right', showSlider: 'mouseover', renderCharacters: true, maxColumn: 80, scale: 1 },
            largeFileOptimizations: true,
            scrollBeyondLastLine: false,
            smoothScrolling: true,
            wordWrap: 'off',
            tabSize: 4,
            insertSpaces: true,
            renderValidationDecorations: 'on',
            bracketPairColorization: { enabled: true },
            guides: { indentation: true, bracketPairs: true, highlightActiveIndentation: true },
            folding: false,
            foldingHighlight: true,
            showFoldingControls: 'mouseover',
            glyphMargin: false,
            lineDecorationsWidth: 4,
            lineNumbersMinChars: this.lineNumbersMinChars(),
            renderWhitespace: 'selection',
            renderControlCharacters: true,
            matchBrackets: 'always',
            selectionHighlight: true,
            occurrencesHighlight: 'singleFile',
            formatOnPaste: !largeFile,
            formatOnType: !largeFile,
            quickSuggestions: largeFile ? false : { other: true, comments: false, strings: false },
            suggestOnTriggerCharacters: !largeFile,
            wordBasedSuggestions: largeFile ? 'off' : 'currentDocument',
            cursorBlinking: 'smooth',
            cursorSmoothCaretAnimation: 'on',
            stickyScroll: { enabled: !largeFile },
            scrollbar: { verticalScrollbarSize: 11, horizontalScrollbarSize: 11 },
            padding: { top: 12, bottom: 18 },
            fixedOverflowWidgets: true,
            theme: this.props.theme === 'light' ? 'nextmux-codex-light' : 'nextmux-codex-dark',
            readOnly: Boolean(this.props.readOnly)
        };
    }

    protected createModel(content: string, suffix: string): monaco.editor.ITextModel {
        const key = `${this.props.uri}::${suffix}`;
        const acquired = acquireNextMuxEditorModel(key, content, this.language());
        const model = acquired.model;
        if (!acquired.reused) this.newlyCreatedModelKeys.add(key);
        this.modelCacheKeys.push(key);
        this.models.push(model);
        return model;
    }

    protected bindModel(model: monaco.editor.ITextModel, side: 'before' | 'current', editor: monaco.editor.IStandaloneCodeEditor): void {
        // Monaco's diff wrapper disables the minimap every time it forwards options.
        // Restore the modified editor's minimap after that synchronous update.
        if (side === 'current') this.disposables.push(editor.onDidChangeConfiguration(event => {
            if (event.hasChanged(monaco.editor.EditorOption.minimap)
                && editor.getOption(monaco.editor.EditorOption.minimap).enabled !== !Boolean(this.props.largeFile)) {
                editor.updateOptions({ minimap: { enabled: !Boolean(this.props.largeFile) } });
            }
        }));
        // A cached model may contain an unsaved draft. Its baseline remains
        // the saved file, so undoing after a tab switch can become clean again.
        const rawBaseline = side === 'before' ? this.props.beforeContent ?? this.props.content : this.props.content;
        const modelValue = model.getValue();
        const baseline = this.normalizeModelEol(rawBaseline);
        this.baselineBySide.set(side, baseline);
        this.dirtyBySide.set(side, this.normalizeModelEol(modelValue) !== baseline);
        this.validateModel(model);
        this.disposables.push(model.onDidChangeContent(() => {
            const value = model.getValue();
            this.dirtyBySide.set(side, this.normalizeModelEol(value) !== this.baselineBySide.get(side));
            this.validateModel(model);
            this.props.onContentChange(side, value);
            this.props.onDirty([...this.dirtyBySide.values()].some(Boolean));
        }));
        this.disposables.push(editor.onDidFocusEditorText(() => {
            this.lastFocusedEditor = editor;
            this.props.onFocus(side);
        }));
        this.disposables.push(editor.onDidScrollChange(event => {
            if (!event.scrollTopChanged && !event.scrollLeftChanged) return;
            this.props.onScrollPositionChange?.({ top: editor.getScrollTop(), left: editor.getScrollLeft() });
        }));
        editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => { if (!this.props.readOnly) this.props.onSave(side, model.getValue()); });
        // Find and replace remain Monaco's built-in actions. Keeping them out
        // of this local binding list lets Monaco and the user's keymap decide
        // the shortcut, including custom remappings on macOS and Windows.
        editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyZ, () => { if (!this.props.readOnly) void model.undo(); });
        editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyMod.Shift | monaco.KeyCode.KeyZ, () => { if (!this.props.readOnly) void model.redo(); });
        editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyY, () => { if (!this.props.readOnly) void model.redo(); });
        editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyV, () => void this.runEditingCommand('paste').catch(this.props.onClipboardError));
        editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyC, () => void this.runEditingCommand('copy').catch(this.props.onClipboardError));
        editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyX, () => void this.runEditingCommand('cut').catch(this.props.onClipboardError));
    }

    protected applyInitialEditorDrafts(): void {
        const pair = this.editor && 'getModifiedEditor' in this.editor ? this.editor.getModel() : undefined;
        for (const side of ['before', 'current'] as const) {
            const draft = this.props.initialDrafts?.[side];
            const model = side === 'before' ? pair?.original : pair?.modified || this.models.at(-1);
            // A reused model already carries its undo stack. Only reconcile it
            // when the parent snapshot actually differs (for example an
            // external save), so a normal tab switch never calls setValue.
            if (draft !== undefined && model && this.normalizeModelEol(model.getValue()) !== this.normalizeModelEol(draft)) {
                model.setValue(draft);
            }
        }
    }

    protected acceptRefreshedSource(previous: Readonly<NextMuxFileEditorProps>): void {
        const pair = this.editor && 'getModifiedEditor' in this.editor ? this.editor.getModel() : undefined;
        const sides: readonly ('before' | 'current')[] = this.props.beforeContent === undefined ? ['current'] : ['before', 'current'];
        const textareas = this.host?.querySelectorAll<HTMLTextAreaElement>('textarea');
        for (const [index, side] of sides.entries()) {
            const prior = side === 'before' ? previous.beforeContent : previous.content;
            const next = side === 'before' ? this.props.beforeContent : this.props.content;
            if (prior === undefined || next === undefined) continue;
            const model = side === 'before' ? pair?.original : pair?.modified || this.models.at(-1);
            const textarea = !model ? textareas?.[index] : undefined;
            // Only reconcile the clean source we actually replaced. Typing
            // between the parent's disk read and this render remains a draft.
            const value = model?.getValue() ?? textarea?.value;
            if (value === undefined || this.normalizeModelEol(value) !== this.normalizeModelEol(prior)) {
                if (textarea) {
                    this.baselineBySide.set(side, this.normalizeModelEol(next));
                    this.dirtyBySide.set(side, value === undefined || this.normalizeModelEol(value) !== this.normalizeModelEol(next));
                    this.props.onContentChange(side, textarea.value);
                }
                continue;
            }
            this.baselineBySide.set(side, this.normalizeModelEol(next));
            this.dirtyBySide.set(side, false);
            if (model && this.normalizeModelEol(value) !== this.normalizeModelEol(next)) {
                model.pushStackElement();
                model.pushEditOperations([], [{ range: model.getFullModelRange(), text: next }], () => null);
                model.pushStackElement();
            } else if (textarea) {
                textarea.value = next;
                this.props.onContentChange(side, next);
            }
        }
        if (!this.models.length) this.props.onDirty([...this.dirtyBySide.values()].some(Boolean));
    }

    protected acceptSavedRevision(): void {
        const pair = this.editor && 'getModifiedEditor' in this.editor
            ? (this.editor as monaco.editor.IStandaloneDiffEditor).getModel() : undefined;
        const current = pair?.modified || this.models.find(model => this.normalizeModelEol(model.getValue()) === this.normalizeModelEol(this.props.content)) || this.models[this.models.length - 1];
        if (!current) return;
        if (pair?.original) {
            const before = pair.original.getValue();
            const baseline = this.normalizeModelEol(before) === this.normalizeModelEol(this.props.content) ? this.props.content : this.props.beforeContent;
            pair.original.pushStackElement();
            if (baseline !== undefined) this.baselineBySide.set('before', this.normalizeModelEol(baseline));
            this.dirtyBySide.set('before', baseline === undefined || this.normalizeModelEol(before) !== this.normalizeModelEol(baseline));
            this.props.onContentChange('before', before);
        }
        current.pushStackElement();
        this.baselineBySide.set('current', this.normalizeModelEol(this.props.content));
        this.dirtyBySide.set('current', this.normalizeModelEol(current.getValue()) !== this.normalizeModelEol(this.props.content));
        this.props.onContentChange('current', current.getValue());
        this.props.onDirty([...this.dirtyBySide.values()].some(Boolean));
    }

    protected collapseDiffEditorPreservingHistory(): void {
        const diff = this.editor as monaco.editor.IStandaloneDiffEditor;
        const pair = diff.getModel();
        const current = pair && [pair.modified, pair.original].find(model => this.normalizeModelEol(model.getValue()) === this.normalizeModelEol(this.props.content))
            || pair?.modified
            || this.models[this.models.length - 1];
        for (const disposable of this.disposables.splice(0)) disposable.dispose();
        diff.dispose();
        this.editor = undefined;
        const currentIndex = current ? this.models.indexOf(current) : -1;
        const currentKey = currentIndex >= 0 ? this.modelCacheKeys[currentIndex] : undefined;
        this.modelCacheKeys.forEach(key => { if (key !== currentKey) releaseNextMuxEditorModel(key); });
        this.models = current ? [current] : [];
        this.modelCacheKeys = currentKey ? [currentKey] : [];
        this.newlyCreatedModelKeys.clear();
        this.dirtyBySide.clear();
        this.baselineBySide.clear();
        if (!current || !this.host) {
            this.disposeEditor();
            this.createEditorSafely();
            return;
        }
        const editor = monaco.editor.create(this.host, { ...this.editorOptions(), model: current });
        this.bindModel(current, 'current', editor);
        current.pushStackElement();
        this.baselineBySide.set('current', this.normalizeModelEol(this.props.content));
        this.dirtyBySide.set('current', this.normalizeModelEol(current.getValue()) !== this.normalizeModelEol(this.props.content));
        this.props.onContentChange('current', current.getValue());
        this.props.onDirty(this.dirtyBySide.get('current') || false);
        this.editor = editor;
        this.observeEditorLayout();
        this.scheduleInitialScrollPosition();
    }

    protected validateModel(model: monaco.editor.ITextModel): void {
        const markers: monaco.editor.IMarkerData[] = [];
        if (this.props.largeFile) {
            monaco.editor.setModelMarkers(model, 'nextmux-editor', markers);
            return;
        }
        const language = model.getLanguageId();
        if (language === 'json') {
            try {
                JSON.parse(model.getValue().replace(/^\s*\/\/.*$/gm, ''));
            } catch (error) {
                const message = error instanceof Error ? error.message : 'JSON 格式错误';
                const offset = Number(message.match(/position\s+(\d+)/i)?.[1] || 0);
                const position = model.getPositionAt(Math.max(0, Math.min(offset, model.getValueLength())));
                markers.push({
                    severity: monaco.MarkerSeverity.Error,
                    message,
                    startLineNumber: position.lineNumber,
                    startColumn: position.column,
                    endLineNumber: position.lineNumber,
                    endColumn: position.column + 1
                });
            }
        }
        monaco.editor.setModelMarkers(model, 'nextmux-editor', markers);
    }

    protected createEditor(): void {
        if (!this.host) return;
        ensureNextMuxEditorLanguages();
        this.registerThemes();
        this.host.classList.toggle('is-inline-current', this.props.beforeContent !== undefined && !Boolean(this.props.renderSideBySide));
        if (this.props.beforeContent !== undefined) {
            const original = this.createModel(this.props.beforeContent, 'before');
            const modified = this.createModel(this.props.content, 'current');
            const editor = monaco.editor.createDiffEditor(this.host, {
                ...this.editorOptions(),
                originalEditable: !this.props.readOnly,
                renderSideBySide: Boolean(this.props.renderSideBySide),
                enableSplitViewResizing: true,
                ignoreTrimWhitespace: false,
                renderOverviewRuler: Boolean(this.props.renderSideBySide),
                renderMarginRevertIcon: false,
                renderGutterMenu: false
            });
            editor.setModel({ original, modified });
            editor.getOriginalEditor().updateOptions({ lineNumbers: this.props.renderSideBySide ? 'on' : 'off',
                lineNumbersMinChars: this.props.renderSideBySide ? this.lineNumbersMinChars() : 0,
                glyphMargin: false, folding: false, lineDecorationsWidth: this.props.renderSideBySide ? 4 : 0 });
            editor.getModifiedEditor().updateOptions({ lineNumbers: 'on', lineNumbersMinChars: this.lineNumbersMinChars(),
                glyphMargin: false, folding: false, lineDecorationsWidth: 4,
                minimap: { enabled: !Boolean(this.props.largeFile), autohide: 'none', side: 'right', showSlider: 'mouseover', renderCharacters: true, maxColumn: 80, scale: 1 } });
            this.bindModel(original, 'before', editor.getOriginalEditor());
            this.bindModel(modified, 'current', editor.getModifiedEditor());
            this.editor = editor;
        } else {
            const model = this.createModel(this.props.content, 'current');
            const editor = monaco.editor.create(this.host, { ...this.editorOptions(), model });
            this.bindModel(model, 'current', editor);
            this.editor = editor;
        }
        this.applyInitialEditorDrafts();
        this.observeEditorLayout();
    }

    protected createEditorSafely(): void {
        try {
            this.createEditor();
        } catch {
            this.disposeEditor();
            this.createFallbackEditor();
        }
    }

    protected createFallbackEditor(): void {
        if (!this.host) return;
        const values: readonly ['before' | 'current', string][] = this.props.beforeContent === undefined
            ? [['current', this.props.content]]
            : [['before', this.props.beforeContent], ['current', this.props.content]];
        this.host.classList.add('is-fallback');
        if (values.length > 1 && Boolean(this.props.renderSideBySide)) this.host.classList.add('is-diff');
        for (const [side, initial] of values) {
            const textarea = document.createElement('textarea');
            textarea.value = this.props.initialDrafts?.[side] ?? initial;
            textarea.readOnly = Boolean(this.props.readOnly);
            textarea.hidden = !this.props.renderSideBySide && side === 'before';
            textarea.spellcheck = false;
            textarea.setAttribute('data-nmx-literal', 'true');
            textarea.setAttribute('aria-label', `${this.props.name} · ${side}`);
            this.baselineBySide.set(side, this.normalizeModelEol(initial));
            this.dirtyBySide.set(side, this.normalizeModelEol(textarea.value) !== this.normalizeModelEol(initial));
            const onInput = () => {
                this.dirtyBySide.set(side, this.normalizeModelEol(textarea.value) !== this.baselineBySide.get(side));
                this.props.onContentChange(side, textarea.value);
                this.props.onDirty([...this.dirtyBySide.values()].some(Boolean));
            };
            const onFocus = () => this.props.onFocus(side);
            const onScroll = () => this.props.onScrollPositionChange?.({ top: textarea.scrollTop, left: textarea.scrollLeft });
            const onKeyDown = (event: KeyboardEvent) => {
                if (!(event.ctrlKey || event.metaKey) || event.key.toLocaleLowerCase() !== 's') return;
                event.preventDefault();
                if (!this.props.readOnly) this.props.onSave(side, textarea.value);
            };
            textarea.addEventListener('input', onInput);
            textarea.addEventListener('focus', onFocus);
            textarea.addEventListener('keydown', onKeyDown);
            textarea.addEventListener('scroll', onScroll, { passive: true });
            this.fallbackDisposables.push(() => {
                textarea.removeEventListener('input', onInput);
                textarea.removeEventListener('focus', onFocus);
                textarea.removeEventListener('keydown', onKeyDown);
                textarea.removeEventListener('scroll', onScroll);
            });
            this.host.appendChild(textarea);
            this.props.onContentChange(side, textarea.value);
        }
        this.props.onDirty([...this.dirtyBySide.values()].some(Boolean));
    }

    protected scheduleRevealRange(): void {
        if (!this.props.revealRange) return;
        if (this.revealAnimationFrame !== undefined) window.cancelAnimationFrame(this.revealAnimationFrame);
        this.revealAnimationFrame = window.requestAnimationFrame(() => {
            this.revealAnimationFrame = undefined;
            this.revealRangeInEditor();
        });
    }

    protected scrollEditor(): monaco.editor.IStandaloneCodeEditor | undefined {
        if (!this.editor) return undefined;
        return 'getModifiedEditor' in this.editor ? this.editor.getModifiedEditor() : this.editor;
    }

    protected scheduleInitialScrollPosition(): void {
        // A requested activity range is authoritative: it deliberately moves
        // the editor to the changed lines instead of restoring an old viewport.
        if (!this.props.initialScrollPosition || this.props.revealRange) return;
        if (this.scrollRestoreAnimationFrame !== undefined) window.cancelAnimationFrame(this.scrollRestoreAnimationFrame);
        this.scrollRestoreAnimationFrame = window.requestAnimationFrame(() => {
            this.scrollRestoreAnimationFrame = undefined;
            const position = this.props.initialScrollPosition;
            if (!position) return;
            const editor = this.scrollEditor();
            if (editor) {
                editor.setScrollPosition({ scrollTop: position.top, scrollLeft: position.left });
                return;
            }
            const textarea = this.host?.querySelector<HTMLTextAreaElement>('textarea:last-of-type');
            if (textarea) {
                textarea.scrollTop = position.top;
                textarea.scrollLeft = position.left;
            }
        });
    }

    protected revealRangeInEditor(): void {
        const requested = this.props.revealRange;
        if (!requested) return;
        const codeEditor = this.editor
            ? ('getModifiedEditor' in this.editor ? this.editor.getModifiedEditor() : this.editor)
            : undefined;
        const model = codeEditor?.getModel();
        if (codeEditor && model) {
            const startLine = Math.max(1, Math.min(model.getLineCount(), requested.startLine));
            const endLine = Math.max(startLine, Math.min(model.getLineCount(), requested.endLine));
            const range = new monaco.Range(startLine, 1, endLine, model.getLineMaxColumn(endLine));
            codeEditor.setSelection(range);
            codeEditor.revealRangeInCenter(range, monaco.editor.ScrollType.Smooth);
            return;
        }
        const textarea = this.host?.querySelector<HTMLTextAreaElement>('textarea:last-of-type');
        if (!textarea) return;
        const lines = textarea.value.split(/\r?\n/);
        const startLine = Math.max(1, Math.min(lines.length, requested.startLine));
        const endLine = Math.max(startLine, Math.min(lines.length, requested.endLine));
        const offsetAt = (line: number): number => lines.slice(0, Math.max(0, line - 1)).reduce((total, value) => total + value.length + 1, 0);
        textarea.setSelectionRange(offsetAt(startLine), offsetAt(endLine) + (lines[endLine - 1]?.length || 0));
        textarea.scrollTop = Math.max(0, (startLine - 3) * 22);
    }

    protected disposeEditor(): void {
        this.resizeObserver?.disconnect();
        this.resizeObserver = undefined;
        if (this.layoutAnimationFrame !== undefined) {
            window.cancelAnimationFrame(this.layoutAnimationFrame);
            this.layoutAnimationFrame = undefined;
        }
        if (this.revealAnimationFrame !== undefined) {
            window.cancelAnimationFrame(this.revealAnimationFrame);
            this.revealAnimationFrame = undefined;
        }
        if (this.scrollRestoreAnimationFrame !== undefined) {
            window.cancelAnimationFrame(this.scrollRestoreAnimationFrame);
            this.scrollRestoreAnimationFrame = undefined;
        }
        for (const disposable of this.disposables.splice(0)) {
            if (disposable && typeof disposable.dispose === 'function') disposable.dispose();
        }
        this.editor?.dispose();
        this.editor = undefined;
        this.lastFocusedEditor = undefined;
        for (const key of this.modelCacheKeys.splice(0)) releaseNextMuxEditorModel(key);
        this.models.splice(0);
        this.newlyCreatedModelKeys.clear();
        for (const dispose of this.fallbackDisposables.splice(0)) dispose();
        if (this.host) {
            this.host.replaceChildren();
            this.host.classList.remove('is-fallback', 'is-diff');
        }
        this.dirtyBySide.clear();
        this.baselineBySide.clear();
    }

    /** 查找 / 替换 from the file tab's menu (nmx-editor-find), in the editor that last had focus. */
    protected readonly runFindCommand = (event: Event): void => {
        const editor = this.commandEditor();
        if (!editor) return;
        event.preventDefault();
        editor.focus();
        void editor.getAction((event as CustomEvent<string>).detail === 'replace' ? 'editor.action.startFindReplaceAction' : 'actions.find')?.run();
    };

    protected setHost = (host: HTMLDivElement | null): void => {
        this.host?.removeEventListener('nmx-editor-find', this.runFindCommand);
        this.host = host;
        host?.addEventListener('nmx-editor-find', this.runFindCommand);
    };

    override render(): React.ReactNode {
        return <div className='nmx-monaco-file-editor' ref={this.setHost}
            data-reveal-start-line={this.props.revealRange?.startLine}
            data-reveal-end-line={this.props.revealRange?.endLine}></div>;
    }
}

/** A current iPhone Safari: sites that pick their layout from the user agent send the phone version. */
const MOBILE_BROWSER_USER_AGENT = 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1';

interface NextMuxBrowserViewProps {
    readonly id: string;
    readonly url: string;
    readonly title: string;
    readonly active: boolean;
    readonly mobile?: boolean;
    readonly onLocation: (url: string) => void;
    readonly onTitle: (title: string) => void;
}

class NextMuxBrowserView extends React.PureComponent<NextMuxBrowserViewProps> {
    protected webview: (HTMLElement & { getURL?: () => string; loadURL?: (url: string) => Promise<void> }) | null = null;
    /** The desktop user agent to go back to after the phone view. */
    protected desktopUserAgent: string | undefined;
    protected readonly initialUrl = this.props.url;

    override componentDidUpdate(previous: NextMuxBrowserViewProps): void {
        if (Boolean(previous.mobile) !== Boolean(this.props.mobile)) {
            // Phone or desktop: the page reloads with the matching user agent (the width follows the CSS frame).
            try {
                const view = this.webview as (HTMLElement & { setUserAgent?: (agent: string) => void; getUserAgent?: () => string; reload?: () => void }) | null;
                if (this.props.mobile) {
                    const current = view?.getUserAgent?.();
                    if (current && current !== MOBILE_BROWSER_USER_AGENT) this.desktopUserAgent = current;
                    view?.setUserAgent?.(MOBILE_BROWSER_USER_AGENT);
                } else if (this.desktopUserAgent) {
                    view?.setUserAgent?.(this.desktopUserAgent);
                } else {
                    // Opened as a phone: the webview's own agent string without the phone override.
                    view?.setUserAgent?.(navigator.userAgent);
                }
                view?.reload?.();
            } catch { /* not attached yet: the useragent attribute applies on load */ }
        }
        if (previous.url === this.props.url) return;
        try {
            if (this.webview?.getURL?.() !== this.props.url) void this.webview?.loadURL?.(this.props.url).catch(() => undefined);
        } catch { /* The initial src attaches before guest methods become available. */ }
    }

    override componentDidMount(): void {
        this.bindEvents();
    }

    override componentWillUnmount(): void {
        this.unbindEvents();
    }

    protected readonly navigate = (event: Event): void => {
        const url = (event as Event & { readonly url?: string }).url;
        if (url) this.props.onLocation(url);
    };

    protected readonly titleChanged = (event: Event): void => {
        const title = (event as Event & { readonly title?: string }).title;
        if (title) this.props.onTitle(title);
    };

    protected bindEvents(): void {
        this.webview?.addEventListener('did-navigate', this.navigate);
        this.webview?.addEventListener('did-navigate-in-page', this.navigate);
        this.webview?.addEventListener('page-title-updated', this.titleChanged);
    }

    protected unbindEvents(): void {
        this.webview?.removeEventListener('did-navigate', this.navigate);
        this.webview?.removeEventListener('did-navigate-in-page', this.navigate);
        this.webview?.removeEventListener('page-title-updated', this.titleChanged);
    }

    protected readonly setWebview = (node: HTMLElement | null): void => {
        if (node === this.webview) return;
        this.unbindEvents();
        this.webview = node;
        this.bindEvents();
    };

    override render(): React.ReactNode {
        return React.createElement('webview', {
            // The parent keeps one webview mounted per browser tab.  A global
            // reload key would destroy page history and scroll state whenever
            // another tab navigates.
            key: this.props.id,
            ref: this.setWebview,
            src: this.initialUrl,
            title: this.props.title,
            'aria-hidden': !this.props.active,
            ...(this.props.mobile ? { useragent: MOBILE_BROWSER_USER_AGENT } : {}),
            partition: 'persist:nextmux-browser',
            webpreferences: 'contextIsolation=yes,nodeIntegration=no,sandbox=yes'
        });
    }
}

type BillingUsageRecord = PlatformAccountOverview['usage'][number];

function usageRecordPromptTokens(record: BillingUsageRecord): number | null {
    const input = Number.isFinite(record.inputTokens) ? Math.max(0, record.inputTokens) : 0;
    const cached = Number.isFinite(record.cachedInputTokens) ? Math.max(0, record.cachedInputTokens) : 0;
    const writes = Number.isFinite(record.cacheWriteTokens) ? Math.max(0, record.cacheWriteTokens) : 0;
    if ((cached > 0 || writes > 0) && record.inputIncludesCached === undefined) return null;
    return record.inputIncludesCached === false ? input + cached + writes : input;
}

function usageRecordTotalTokens(record: BillingUsageRecord): number | null {
    const prompt = usageRecordPromptTokens(record);
    return prompt === null ? null : prompt + Math.max(0, Number.isFinite(record.outputTokens) ? record.outputTokens : 0);
}

