    protected relayOfferingIsFull(offering: PlatformOffering, scope: PublicMerchantCapacityScope = this.activeSection === 'comic' ? 'comic' : 'coding'): boolean {
        return this.relayOfferingIdIsFull(this.offeringMerchantId(offering), offering.id, scope);
    }

    protected relayOfferingIdIsFull(merchantId: string | undefined, offeringId: string | undefined, scope: PublicMerchantCapacityScope = 'coding'): boolean {
        return relayOfferingIsFull(this.relayCapacitySnapshot, merchantId, offeringId, scope);
    }

    /** What the pickers' memoized lists depend on for one merchant: its observed state, full offerings and their expiry. */
    protected relayCapacityKey(merchantId: string, scope: PublicMerchantCapacityScope = 'coding'): string {
        const snapshot = this.relayCapacitySnapshot;
        const entry = snapshot?.scope === scope ? snapshot.merchants.find(item => item.merchantId === merchantId) : undefined;
        return entry && entry.expiresAt > Date.now() && (entry.state === 'full' || entry.fullOfferingIds?.length)
            ? `${entry.state}|${(entry.fullOfferingIds || []).join(',')}` : '';
    }

