    protected conversationAgentRun(sessionId = this.activeCodingSessionId || ''): ConversationAgentRun {
        let run = this.conversationAgentRuns.get(sessionId);
        if (!run) {
            run = createConversationAgentRun(sessionId);
            run.lastRunPermissionMode = this.defaultPermissionMode;
            this.conversationAgentRuns.set(sessionId, run);
        }
        return run;
    }

