    protected readonly conversationReads = new ConversationReadTracker({
        read: (ids, noticeIds) => this.platformService.readConversationReceipts(ids, noticeIds),
        mark: value => this.platformService.markConversationRead(value),
        changed: () => { if (!this.isDisposed) this.update(); },
        broadcast: value => this.conversationReceiptChannel?.postMessage(value)
    });

    /**
     * The conversation's notice, including a computer tool that waits for a macOS permission: that wait lives in this
     * window rather than in the run's events, and still asks the user for something (audit A06-02).
     */
    protected conversationNotice(sessionId: string, latest: Parameters<ConversationReadTracker['notice']>[1]): ConversationAttention | undefined {
        const notice = this.conversationReads.notice(sessionId, latest);
        const wait = this.computerPermissionWaits?.get(sessionId);
        if (notice || !wait || latest?.stage !== 'running') return notice;
        return { sessionId, noticeId: `system-permission:${wait.requestId}`, noticedAt: wait.since, kind: 'permission' };
    }
    /**
     * Completion timestamps are persisted as part of each turn.  Date.now()
     * can return the same millisecond for two terminal transitions, while
     * notice IDs contain random UUIDs and therefore cannot order those
     * transitions.  Keep a small per-conversation high-water mark and bump a
     * timestamp when a turn first enters a terminal state.  Old turns keep
     * their stored values and use the conservative equal-time attention rule.
     */
    protected readonly conversationCompletionTimes = new Map<string, number>();
