    protected cloneInMemoryTurnAttachmentsForBranch(
        sourceSessionId: string,
        branchSessionId: string,
        turns: readonly CodingTurnRecord[]
    ): void {
        for (const turn of turns) {
            for (const attachment of turn.attachments || []) {
                const payload = this.turnAttachmentPayloads.get(
                    this.turnAttachmentPayloadKey(sourceSessionId, attachment.id)
                );
                if (!payload) continue;
                this.turnAttachmentPayloads.set(
                    this.turnAttachmentPayloadKey(branchSessionId, attachment.id),
                    { ...payload, attachment: { ...payload.attachment } }
                );
            }
        }
    }
