                    const limitTokens = entry && typeof entry === 'object' ? normalizeContextWindowTokens((entry as { limitTokens?: unknown }).limitTokens) : undefined;
                    const updatedAt = entry && typeof entry === 'object' && typeof (entry as { updatedAt?: unknown }).updatedAt === 'number' ? (entry as { updatedAt: number }).updatedAt : 0;
                    return typeof key === 'string' && key.length <= 400 && limitTokens !== undefined ? [[key, { limitTokens, updatedAt }] as const] : [];
