            'f90', 'f95', 'pas', 'd', 'sv', 'svh', 'vhd', 'vhdl', 'qml', 'gd', 'hx', 'coffee', 'pug', 'hbs', 'handlebars', 'mustache', 'ejs',
            'erb', 'njk', 'liquid', 'twig', 'jinja', 'j2', 'haml', 'slim', 'razor', 'cshtml', 'xaml', 'wxml', 'wxss', 'applescript', 'ahk',
